class Konsol:
    def gonder(self, mesaj):
        print("Bildirim:", mesaj)
class SiparisServisi:
    def __init__(self, depo, bildirim):
        self.depo = depo
        self.bildirim = bildirim
    def olustur(self, urun):
        self.depo.kaydet(urun)
        self.bildirim.gonder(f"{urun} alındı")

